+    /// <summary>Extracts readable text snippets from DuckDuckGo Lite HTML.</summary>
+    private static List<string> ExtractSnippets(string html)
+    {
+        var results = new List<string>();
+        // DuckDuckGo Lite wraps result snippets in <td> with class "result-snippet"
+        // and links in <a class="result-link">
+        var snippetMarker = "result-snippet";
+        var idx = 0;
+
+        while ((idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
+        {
+            // Find the closing > of the td tag
+            var start = html.IndexOf('>', idx);
+            if (start < 0) break;
+            start++;
+
+            var end = html.IndexOf("</td>", start, StringComparison.OrdinalIgnoreCase);
+            if (end < 0) break;
+
+            var text = StripHtml(html[start..end]).Trim();
