using System.ComponentModel;
using System.Net;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

// ── Bootstrap ──────────────────────────────────────────────────────────────────
var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var notebook = new Notebook();
var researchTools = new ResearchTools(notebook);

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// ── Configure the agent ────────────────────────────────────────────────────────
var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. AIFunctionFactory.Create(researchTools)],
    },
}, services: host.Services);

agent.Instructions =
    """
    You are a research agent. Your goal is to research a topic thoroughly by
    searching the web multiple times and taking notes on important findings.

    Workflow:
    1. Break the topic into 2-3 key sub-questions.
    2. For each sub-question, call web_search to find information.
    3. For each useful finding, call add_note to save it with a source label.
    4. After researching, call get_notes to review everything you collected.
    5. Produce a final summary that synthesizes ALL your notes into a coherent
       report with key takeaways.

    Always search at least twice and take at least 3 notes before summarizing.
    """;

// ── Run the conversation ───────────────────────────────────────────────────────
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest breakthroughs in quantum computing in 2025";

Console.WriteLine($"🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a detailed summary: {topic}",
    session))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

