81. 
82. /// <summary>Persistent notebook that stores research notes in memory.</summary>
83. public sealed class Notebook
84. {
85.     private readonly List<(string Source, string Content)> _notes = [];
86. 
87.     public void Add(string source, string content) => _notes.Add((source, content));
88. 
89.     public IReadOnlyList<(string Source, string Content)> Notes => _notes;
90. }
91. 
92. /// <summary>Tools exposed to the research agent.</summary>
93. public sealed class ResearchTools(Notebook notebook)
94. {
95.     private static readonly HttpClient Http = new()
96.     {
97.         Timeout = TimeSpan.FromSeconds(15),
98.         DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
99.     };
100. 
101.     [Description("Search the web for information on a query. Returns a text snippet of search results.")]
102.     public static async Task<string> web_search(
103.         [Description("The search query string")] string query)
104.     {
105.         try
106.         {
107.             // Use DuckDuckGo Lite (HTML) as a free, no-API-key search endpoint
108.             var encoded = WebUtility.UrlEncode(query);
109.             var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
110.             var html = await Http.GetStringAsync(url);
111. 
112.             // Extract visible text snippets from the result rows
113.             var snippets = ExtractSnippets(html);
114.             if (snippets.Count == 0)
115.                 return $"No results found for: {query}";
116. 
117.             return $"Search results for \"{query}\":\n\n" +
118.                    string.Join("\n---\n", snippets.Take(5));
119.         }
120.         catch (Exception ex)
121.         {
122.             return $"Search failed for \"{query}\": {ex.Message}";
123.         }
124.     }
125. 
126.     [Description("Save a research note with a source label for later reference.")]
127.     public string add_note(
128.         [Description("Label identifying the source (e.g. 'Search: quantum computing')")] string source,
129.         [Description("The content of the note to save")] string content)
130.     {
131.         notebook.Add(source, content);
132.         return $"Note #{notebook.Notes.Count} saved ({content.Length} chars) from \"{source}\".";
133.     }
134. 
135.     [Description("Retrieve all research notes collected so far.")]
136.     public string get_notes()
137.     {
138.         if (notebook.Notes.Count == 0)
139.             return "No notes have been taken yet.";
140. 
141.         return string.Join("\n\n", notebook.Notes.Select((n, i) =>
142.             $"[Note {i + 1}] Source: {n.Source}\n{n.Content}"));
143.     }
144. 
145.     /// <summary>Extracts readable text snippets from DuckDuckGo Lite HTML.</summary>
146.     private static List<string> ExtractSnippets(string html)
147.     {
148.         var results = new List<string>();
149.         // DuckDuckGo Lite wraps result snippets in <td> with class "result-snippet"
150.         // and links in <a class="result-link">
151.         var snippetMarker = "result-snippet";
152.         var idx = 0;
153. 
154.         while ((idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
155.         {
156.             // Find the closing > of the td tag
157.             var start = html.IndexOf('>', idx);
158.             if (start < 0) break;
159.             start++;
160. 
161.             var end = html.IndexOf("</td>", start, StringComparison.OrdinalIgnoreCase);
162.             if (end < 0) break;
163. 
164.             var text = StripHtml(html[start..end]).Trim();
165.             if (text.Length > 20)
166.                 results.Add(text);
167. 
168.             idx = end;
169.         }
170. 
171.         // Fallback: if no result-snippet found, grab text from body
172.         if (results.Count == 0)
173.         {
174.             var body = StripHtml(html);
175.             if (body.Length > 200)
176.                 results.Add(body[..Math.Min(2000, body.Length)]);
177.         }
178. 
179.         return results;
180.     }
181. 
182.     private static string StripHtml(string html)
183.     {
184.         var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
185.         text = WebUtility.HtmlDecode(text);
186.         text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
187.         return text.Trim();
188.     }
189. }
