 /// <summary>Persistent notebook that stores research notes in memory.</summary>
 public sealed class Notebook
 {
     private readonly List<(string Source, string Content)> _notes = [];

     public void Add(string source, string content) => _notes.Add((source, content));

     public IReadOnlyList<(string Source, string Content)> Notes => _notes;
 }

 /// <summary>Tools exposed to the research agent.</summary>
 public sealed class ResearchTools(Notebook notebook)
 {
     private static readonly HttpClient Http = new()
     {
         Timeout = TimeSpan.FromSeconds(15),
         DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
     };

     [Description("Search the web for information on a query. Returns a text snippet of search results.")]
     public static async Task<string> web_search(
         [Description("The search query string")] string query)
     {
         try
         {
             // Use DuckDuckGo Lite (HTML) as a free, no-API-key search endpoint
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
             var html = await Http.GetStringAsync(url);

             // Extract visible text snippets from the result rows
             var snippets = ExtractSnippets(html);
             if (snippets.Count == 0)
                 return $"No results found for: {query}";

             return $"Search results for \"{query}\":\n\n" +
                    string.Join("\n---\n", snippets.Take(5));
         }
         catch (Exception ex)
         {
             return $"Search failed for \"{query}\": {ex.Message}";
         }
     }

     [Description("Save a research note with a source label for later reference.")]
     public string add_note(
         [Description("Label identifying the source (e.g. 'Search: quantum computing')")] string source,
         [Description("The content of the note to save")] string content)
     {
         notebook.Add(source, content);
         return $"Note #{notebook.Notes.Count} saved ({content.Length} chars) from \"{source}\".";
     }

     [Description("Retrieve all research notes collected so far.")]
     public string get_notes()
     {
         if (notebook.Notes.Count == 0)
             return "No notes have been taken yet.";

         return string.Join("\n\n", notebook.Notes.Select((n, i) =>
             $"[Note {i + 1}] Source: {n.Source}\n{n.Content}"));
     }

     /// <summary>Extracts readable text snippets from DuckDuckGo Lite HTML.</summary>
     private static List<string> ExtractSnippets(string html)
     {
         var results = new List<string>();
         // DuckDuckGo Lite wraps result snippets in <td> with class "result-snippet"
         // and links in <a class="result-link">
         var snippetMarker = "result-snippet";
         var idx = 0;

         while ((idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
         {
             // Find the closing > of the td tag
             var start = html.IndexOf('>', idx);
             if (start < 0) break;
             start++;

             var end = html.IndexOf("</td>", start, StringComparison.OrdinalIgnoreCase);
             if (end < 0) break;

             var text = StripHtml(html[start..end]).Trim();
             if (text.Length > 20)
                 results.Add(text);

             idx = end;
         }

         // Fallback: if no result-snippet found, grab text from body
         if (results.Count == 0)
         {
             var body = StripHtml(html);
             if (body.Length > 200)
                 results.Add(body[..Math.Min(2000, body.Length)]);
         }

         return results;
     }

     private static string StripHtml(string html)
     {
         var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
         text = WebUtility.HtmlDecode(text);
         text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
         return text.Trim();
     }
 }

