36.         """
37.         You are a research agent. Your goal is to research a topic thoroughly by
38.         searching the web multiple times and taking notes on important findings.
39. 
40.         Workflow:
41.         1. Break the topic into 2-3 key sub-questions.
42.         2. For each sub-question, call web_search to find information.
43.         3. For each useful finding, call add_note to save it with a source label.
44.         4. After researching, call get_notes to review everything you collected.
45.         5. Produce a final summary that synthesizes ALL your notes into a coherent
46.            report with key takeaways.
47. 
48.         Always search at least twice and take at least 3 notes before summarizing.
49.         """,
50.     name: "ResearchAgent",
51.     description: "Researches topics via web search and note-taking.",
52.     tools: tools);
53. 
54. // ── Run ────────────────────────────────────────────────────────────────────────
55. var topic = args.Length > 0
56.     ? string.Join(' ', args)
57.     : "the latest breakthroughs in quantum computing in 2025";
58. 
59. Console.WriteLine($"🔍 Researching: {topic}\n");
60. 
61. var session = await agent.CreateSessionAsync();
62. 
63. await foreach (var update in agent.RunStreamingAsync(
64.     $"Research the following topic and provide a detailed summary: {topic}",
65.     session))
66. {
67.     if (!string.IsNullOrEmpty(update.Text))
68.     {
69.         Console.Write(update.Text);
70.     }
71. }
72. 
