76. 
77. /// <summary>Persistent notebook that stores research notes in memory.</summary>
78. public sealed class Notebook
79. {
80.     private readonly List<(string Source, string Content)> _notes = [];
81. 
82.     public void Add(string source, string content) => _notes.Add((source, content));
83. 
84.     public IReadOnlyList<(string Source, string Content)> Notes => _notes;
85. }
86. 
87. /// <summary>Tools exposed to the research agent.</summary>
88. public sealed class ResearchTools(Notebook notebook)
89. {
90.     private static readonly HttpClient Http = new()
91.     {
92.         Timeout = TimeSpan.FromSeconds(15),
93.         DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
94.     };
95. 
96.     [Description("Search the web for information on a query. Returns a text snippet of search results.")]
97.     public async Task<string> web_search(
98.         [Description("The search query string")] string query)
99.     {
100.         try
101.         {
102.             var encoded = WebUtility.UrlEncode(query);
103.             var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
104.             var html = await Http.GetStringAsync(url);
105. 
106.             var snippets = ExtractSnippets(html);
107.             if (snippets.Count == 0)
108.                 return $"No results found for: {query}";
109. 
110.             return $"Search results for \"{query}\":\n\n" +
111.                    string.Join("\n---\n", snippets.Take(5));
112.         }
113.         catch (Exception ex)
114.         {
115.             return $"Search failed for \"{query}\": {ex.Message}";
116.         }
117.     }
118. 
119.     [Description("Save a research note with a source label for later reference.")]
120.     public string add_note(
121.         [Description("Label identifying the source (e.g. 'Search: quantum computing')")] string source,
122.         [Description("The content of the note to save")] string content)
123.     {
124.         notebook.Add(source, content);
125.         return $"Note #{notebook.Notes.Count} saved ({content.Length} chars) from \"{source}\".";
126.     }
127. 
128.     [Description("Retrieve all research notes collected so far.")]
129.     public string get_notes()
130.     {
131.         if (notebook.Notes.Count == 0)
132.             return "No notes have been taken yet.";
133. 
134.         return string.Join("\n\n", notebook.Notes.Select((n, i) =>
135.             $"[Note {i + 1}] Source: {n.Source}\n{n.Content}"));
136.     }
137. 
138.     private static List<string> ExtractSnippets(string html)
139.     {
140.         var results = new List<string>();
141.         var snippetMarker = "result-snippet";
142.         var idx = 0;
143. 
144.         while ((idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
145.         {
146.             var start = html.IndexOf('>', idx);
147.             if (start < 0) break;
148.             start++;
149. 
150.             var end = html.IndexOf("</td>", start, StringComparison.OrdinalIgnoreCase);
151.             if (end < 0) break;
152. 
153.             var text = StripHtml(html[start..end]).Trim();
154.             if (text.Length > 20)
155.                 results.Add(text);
156. 
157.             idx = end;
158.         }
159. 
160.         if (results.Count == 0)
161.         {
162.             var body = StripHtml(html);
163.             if (body.Length > 200)
164.                 results.Add(body[..Math.Min(2000, body.Length)]);
165.         }
166. 
167.         return results;
168.     }
169. 
170.     private static string StripHtml(string html)
171.     {
172.         var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
173.         text = WebUtility.HtmlDecode(text);
174.         text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
175.         return text.Trim();
176.     }
177. }
