     public string add_note(
         [Description("Label identifying the source (e.g. 'Search: quantum computing')")] string source,
         [Description("The content of the note to save")] string content)
     {
         notebook.Add(source, content);
         return $"Note #{notebook.Notes.Count} saved ({content.Length} chars) from \"{source}\".";
